import { Router, type Request, type Response, type NextFunction } from "express";
import { getLatestReadingByWarehouse, getDevicesByWarehouseId } from "../db/readings-table";
import { getDeviceById } from "../db/devices-table";

export const router = Router();

router.post("/check-alerts", async (req: Request, res: Response) => {
  const { warehouseId } = req.body;

  if (typeof warehouseId !== "number") {
    res.status(400).send("Invalid warehouse ID");
    return;
  }

  const latestReading = getLatestReadingByWarehouse(warehouseId);
  const devices = getDevicesByWarehouseId(warehouseId);

  if (!latestReading || !devices.length) {
    res.send({ alerts: [] });
    return;
  }

  const currentTimestamp = Date.now();
  const heartbeatThreshold = 60 * 1000; // 1 minute
  const readingThreshold = 30; // Example threshold value

  const alerts: string[] = [];

  devices.forEach(device => {
    const deviceReading = getLatestReadingByWarehouse(device.warehouseId);

    if (!deviceReading) {
      alerts.push(`No reading found for device ${device.id}`);
      return;
    }

    const timeDifference = currentTimestamp - deviceReading.timestamp;

    if (timeDifference > heartbeatThreshold) {
      alerts.push(`Missed heartbeat for device ${device.id}`);
    }

    if (Math.abs(deviceReading.value - latestReading.value) > readingThreshold) {
      alerts.push(`Out-of-range reading for device ${device.id}`);
    }
  });

  res.send({ alerts });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
