import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is intended to protect routes related to ticket purchases.
  // For demonstration purposes, let's assume there's a specific path `/purchase-ticket`
  // that should be guarded against overselling.
  if (req.method !== "POST" || req.path !== "/purchase-ticket") {
    return next();
  }

  // In a real implementation, you would fetch the event details and check the ticket count.
  // Since we don't have access to the actual data layer, we'll simulate a check.
  const eventTicketsRemaining = Number(process.env.EVENT_TICKETS_REMAINING);

  if (isNaN(eventTicketsRemaining) || eventTicketsRemaining <= 0) {
    res.status(403).send("Ticket sales have been closed due to high demand.");
    return;
  }

  // If tickets are still available, decrement the count and proceed.
  process.env.EVENT_TICKETS_REMAINING = String(eventTicketsRemaining - 1);
  next();
}

