import { Router, type Request, type Response } from "express";
import { Car, getAllCars, getBookingsByCarId } from "../db/cars-table";
import { insertBooking } from "../db/bookings-table";

export const router = Router();

router.get("/availability", (req: Request, res: Response) => {
  const { carId, startDate, endDate } = req.query;
  const car = getCarById(Number(carId));
  if (!car) {
    res.status(404).send("Car not found");
    return;
  }

  const existingBookings = getBookingsByCarId(Number(carId));
  const isAvailable = existingBookings.every((booking: Booking) => {
    const bookingStartDate = new Date(booking.startDate);
    const bookingEndDate = new Date(booking.endDate);
    const requestedStartDate = new Date(startDate as string);
    const requestedEndDate = new Date(endDate as string);
    return !(requestedStartDate < bookingEndDate && requestedEndDate > bookingStartDate);
  });

  res.json({ isAvailable });
});

router.post("/book", (req: Request, res: Response) => {
  const { carId, customerId, startDate, endDate } = req.body;
  const car = getCarById(Number(carId));
  if (!car) {
    res.status(404).send("Car not found");
    return;
  }

  const existingBookings = getBookingsByCarId(Number(carId));
  const isAvailable = existingBookings.every((booking: Booking) => {
    const bookingStartDate = new Date(booking.startDate);
    const bookingEndDate = new Date(booking.endDate);
    const requestedStartDate = new Date(startDate);
    const requestedEndDate = new Date(endDate);
    return !(requestedStartDate < bookingEndDate && requestedEndDate > bookingStartDate);
  });

  if (!isAvailable) {
    res.status(409).send("Car is not available for the selected dates");
    return;
  }

  insertBooking(Number(carId), Number(customerId), startDate, endDate);
  res.status(201).send("Booking created successfully");
});

